insert into interactive_lesson_seed values ($curriculum$[{"slug":"membaca-bentuk-data","title":"Membaca Bentuk Data","summary":"Bedakan tabel, kolom, dan record melalui data Kampus Mini yang bisa dipilih.","content":"## Misi Kampus Mini\n\nPetugas kampus ingin mengetahui apa yang disimpan di setiap tabel. Temukan record Alya dan bedakan nilai miliknya dari struktur tabelnya.\n\n## Tabel menyimpan satu jenis fakta\n\nDatabase mengumpulkan data yang saling berhubungan. Tabel students menyimpan mahasiswa, courses menyimpan mata kuliah, dan enrollments menyimpan pendaftaran. Satu mahasiswa dapat memiliki beberapa pendaftaran; pendaftaran bukan mahasiswa baru.\n\n**Amati:** buka ketiga tabel. Bandingkan 4 mahasiswa, 3 mata kuliah, dan 6 pendaftaran. Mengapa jumlahnya tidak harus sama?\n\n## Kolom adalah atribut, bukan isinya\n\nPada students, name adalah kolom; Alya adalah salah satu nilainya. cohort mencatat angkatan, sedangkan student_id membedakan mahasiswa. Semua record pada tabel yang sama mengikuti susunan kolom yang sama.\n\n**Coba:** buka students lalu pilih Alya. Tunjuk satu nama kolom dan nilai pada kolom itu. Apakah 2025 adalah kolom atau nilai?\n\n## Record dan schema\n\nSatu baris lengkap, misalnya student_id 1, name Alya, cohort 2025, adalah satu record. Schema menjelaskan nama tabel, kolom, tipe nilai, dan aturan key. Menambah mahasiswa baru mengubah isi record, bukan otomatis menambah kolom.\n\n**Prediksi:** jika Eka ditambahkan sebagai mahasiswa kelima, mana yang berubah: jumlah baris, jumlah kolom, atau keduanya? Jelaskan sebelum melihat materi Write.\n\n## Coba, bandingkan, jelaskan\n\nPilih record pada tampilan 2D. Coba mode 3D untuk mengikuti hubungan yang sama. Kembali ke tabel bila ingin membaca nilainya dengan lebih teliti. Tidak ada query pada materi Relasi.\n\nDua latihan pertama membantumu memeriksa submateri dan bersifat opsional. Practice terakhir wajib untuk membuka materi berikutnya. Semua latihan dapat diulang; hasil Run bukan nilai asesmen.\n","example_sql":null,"exercises":[{"type":"PSEUDOCODE","title":"Temukan tabel yang tepat","prompt":"Di tabel mana kamu mencari daftar mahasiswa, bukan daftar pendaftaran?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"courses","text":"courses"},{"id":"students","text":"students"},{"id":"enrollments","text":"enrollments"}],"subtopic":"Tabel"},"answer":{"choiceId":"students"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Bedakan objek mahasiswa dengan peristiwa pendaftaran mahasiswa pada mata kuliah."}},"position":1,"is_required":false},{"type":"PSEUDOCODE","title":"Kolom atau nilai?","prompt":"Perhatikan students. Mana yang merupakan nama kolom?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"alya","text":"Alya"},{"id":"cohort","text":"cohort"},{"id":"year","text":"2025"}],"subtopic":"Kolom"},"answer":{"choiceId":"cohort"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Nama kolom ada pada header dan dipakai oleh semua record, sedangkan nilai berada di sel."}},"position":2,"is_required":false},{"type":"PSEUDOCODE","title":"Bedakan isi dan struktur","prompt":"Eka ditambahkan ke students dengan tiga atribut yang sama. Apa yang berubah?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"schema","text":"Jumlah kolom bertambah menjadi empat."},{"id":"rows","text":"Jumlah record bertambah; kolom tetap student_id, name, cohort."},{"id":"table","text":"Setiap mahasiswa harus dibuatkan tabel sendiri."}],"subtopic":"Record dan schema"},"answer":{"choiceId":"rows"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Satu mahasiswa tambahan adalah satu baris baru pada struktur yang sudah ada."}},"position":3,"is_required":true}]},{"slug":"key-dan-hubungan-antar-tabel","title":"Key dan Hubungan Antar Tabel","summary":"Ikuti pendaftaran ke mahasiswa dan mata kuliahnya lewat primary key serta foreign key.","content":"## Misi Kampus Mini\n\nCari mata kuliah yang diikuti Alya. Pilih record Alya, lihat pendaftaran terkait, lalu ikuti course_id-nya. Gunakan 2D dan 3D untuk menyelidiki relasi yang sama.\n\n## Primary key: identitas record\n\nPrimary key atau PK membedakan setiap record dalam satu tabel. students.student_id mengidentifikasi mahasiswa; nama dapat sama, tetapi PK tetap unik. PK tidak kosong. Nilai 1 pada students tidak berarti sama dengan nilai 1 pada enrollments karena keduanya mengidentifikasi objek yang berbeda.\n\n**Amati:** bedakan student_id 1 dan enrollment_id 1. Apa yang mereka identifikasi?\n\n## Foreign key: rujukan ke tabel lain\n\nenrollments.student_id merujuk students.student_id, dan enrollments.course_id merujuk courses.course_id. Keduanya foreign key atau FK. Pendaftaran 2 mempunyai student_id 1 dan course_id 20: mahasiswa dan mata kuliahnya ditemukan lewat key, bukan urutan baris atau kemiripan nama.\n\n**Coba:** pilih enrollments #2 dan buka dua tabel terkait. Pastikan pasangan key benar-benar sama.\n\n## Satu-ke-banyak dan tabel penghubung\n\nAlya mempunyai dua record enrollments: satu mahasiswa ke banyak pendaftaran. Satu mata kuliah juga mempunyai banyak pendaftaran. Mahasiswa dan mata kuliah memiliki hubungan banyak-ke-banyak melalui enrollments; score adalah nilai untuk satu pasangan mahasiswa–mata kuliah.\n\n**Jelaskan:** mengapa score disimpan di enrollments, bukan satu kolom score pada students? Pilih Alya dan bandingkan nilai pada dua pendaftarannya.\n\n## Coba, bandingkan, jelaskan\n\nPilih record pada tampilan 2D. Coba mode 3D untuk mengikuti hubungan yang sama. Kembali ke tabel bila ingin membaca nilainya dengan lebih teliti. Tidak ada query pada materi Relasi.\n\nDua latihan pertama membantumu memeriksa submateri dan bersifat opsional. Practice terakhir wajib untuk membuka materi berikutnya. Semua latihan dapat diulang; hasil Run bukan nilai asesmen.\n","example_sql":null,"exercises":[{"type":"PSEUDOCODE","title":"Identitas bukan nama","prompt":"Dua mahasiswa boleh bernama sama. Kolom mana tetap membedakan record pada students?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"name","text":"name"},{"id":"id","text":"student_id"},{"id":"cohort","text":"cohort"}],"subtopic":"Primary key"},"answer":{"choiceId":"id"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Nama dan angkatan dapat berulang. Cari kolom berlabel PK."}},"position":1,"is_required":false},{"type":"PSEUDOCODE","title":"Ikuti foreign key","prompt":"Enrollment #2 memakai course_id 20. Kolom mana dirujuk untuk menemukan mata kuliahnya?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"enrollment","text":"courses.enrollment_id"},{"id":"code","text":"courses.course_code"},{"id":"course","text":"courses.course_id"}],"subtopic":"Foreign key"},"answer":{"choiceId":"course"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Pasangkan FK ke PK tabel tujuan, bukan ke nama atau kode yang tampil."}},"position":2,"is_required":false},{"type":"FLOWCHART","title":"Telusuri pendaftaran Alya","prompt":"Susun alur dari pendaftaran ke mahasiswa dan mata kuliah. Record awal adalah enrollments #2.","starter_code":null,"config":{"public":{"mode":"order","blocks":[{"id":"course","text":"Ikuti course_id 20 ke courses: Basis Data."},{"id":"start","text":"Baca enrollment #2: student_id 1 dan course_id 20."},{"id":"student","text":"Ikuti student_id 1 ke students: Alya."}],"subtopic":"Jalur relasi"},"answer":{"order":["start","student","course"]},"feedback":{"correct":"Urutan tepat. Hubungkan setiap langkah dengan data yang kamu amati.","retry":"Mulai dari record penghubung; gunakan kedua FK untuk menemukan record induk."}},"position":3,"is_required":true}]},{"slug":"memilih-sumber-dan-kolom","title":"Mengambil Data dengan SELECT","summary":"Pilih tabel sumber dan atribut yang diminta tanpa mengubah record.","content":"## Misi Kampus Mini\n\nPetugas hanya membutuhkan kode dan nama mata kuliah. Tampilkan kedua kolom dari courses, bukan nama mahasiswa dari students.\n\n## FROM: tentukan sumber\n\nPertanyaan menentukan jenis fakta yang dibutuhkan. Daftar mata kuliah berasal dari courses; daftar mahasiswa berasal dari students. FROM menentukan tabel sumber.\n\n**Amati:** buka courses dan tunjuk tiga record yang akan dibaca. SELECT tidak mengubah isi tabel.\n\n## SELECT: tentukan kolom\n\nSELECT menentukan kolom hasil. `SELECT course_code, course_name FROM courses;` memilih dua atribut. `SELECT * FROM courses;` membantu inspeksi awal tetapi menampilkan semua kolom. Urutan kolom pada SELECT menjadi urutan kolom hasil.\n\n**Coba:** tambahkan credits, lalu hilangkan course_name. Mengapa jumlah record tetap tiga?\n\n## Bentuk hasil yang bisa dijelaskan\n\nHasil query adalah tabel baru untuk dibaca, bukan pemindahan record sumber. Tanpa ORDER BY, urutan baris tidak dijamin. Contoh memakai ORDER BY course_id agar hasil latihan stabil; pembahasan urutan ada pada materi berikutnya.\n\n```sql\nSELECT course_code, course_name\nFROM courses\nORDER BY course_id;\n```\n\n**Jelaskan:** sumbernya apa, kolomnya apa, dan apakah data asal berubah?\n\n## Coba, bandingkan, jelaskan\n\nGunakan objek data untuk memeriksa record sumber, lalu jalankan contoh di lab. Ubah satu bagian, prediksi ulang, dan bandingkan hasilnya. 3D membantu mengikuti relasi; tabel hasil tetap 2D.\n\nDua latihan pertama membantumu memeriksa submateri dan bersifat opsional. Practice terakhir wajib untuk membuka materi berikutnya. Semua latihan dapat diulang; hasil Run bukan nilai asesmen.\n","example_sql":"SELECT course_code, course_name FROM courses ORDER BY course_id;","exercises":[{"type":"PSEUDOCODE","title":"Pilih sumber informasi","prompt":"Kamu ingin nama dan kode mata kuliah. FROM harus memakai tabel apa?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"student","text":"students"},{"id":"course","text":"courses"},{"id":"enrollment","text":"enrollments"}],"subtopic":"FROM"},"answer":{"choiceId":"course"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Temukan tabel yang memiliki course_code dan course_name."}},"position":1,"is_required":false},{"type":"PSEUDOCODE","title":"Pilih atribut","prompt":"Permintaan hanya kode dan nama mata kuliah. Pilihan SELECT mana paling sesuai?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"all","text":"SELECT *"},{"id":"pair","text":"SELECT course_code, course_name"},{"id":"student","text":"SELECT name, cohort"}],"subtopic":"SELECT"},"answer":{"choiceId":"pair"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Ambil atribut yang diminta dari tabel sumber, tanpa memasukkan atribut mahasiswa."}},"position":2,"is_required":false},{"type":"PSEUDOCODE","title":"Bangun query pertama","prompt":"Susun klausa untuk membaca kode dan nama mata kuliah secara stabil.","starter_code":null,"config":{"public":{"mode":"order","blocks":[{"id":"sort","text":"ORDER BY course_id;"},{"id":"source","text":"FROM courses"},{"id":"columns","text":"SELECT course_code, course_name"}],"subtopic":"Bentuk hasil"},"answer":{"order":["columns","source","sort"]},"feedback":{"correct":"Urutan tepat. Hubungkan setiap langkah dengan data yang kamu amati.","retry":"Urutan penulisan dimulai SELECT, dilanjutkan FROM, lalu ORDER BY."}},"position":3,"is_required":true}]},{"slug":"menyaring-record","title":"Memilih Baris dengan WHERE","summary":"Uji batas nilai serta gabungan kondisi dengan memilih record yang memenuhi syarat.","content":"## Misi Kampus Mini\n\nKampus mencari pendaftaran dengan nilai minimal 80. Perhatikan record bernilai tepat 80: apakah ikut?\n\n## Perbandingan dan batas\n\nWHERE memilih record yang memenuhi kondisi. `score >= 80` menerima 80, sedangkan `score > 80` tidak. `=` membandingkan kesamaan; teks memakai kutip tunggal. WHERE memilih baris, bukan menghapusnya.\n\n**Amati:** pilih enrollment #5 dengan score 80. Prediksi bedanya sebelum mengubah operator.\n\n## AND, OR, dan tanda kurung\n\nAND meminta kedua kondisi benar. OR cukup salah satu kondisi benar. Gunakan tanda kurung saat menggabungkan keduanya agar maksudnya jelas: `(course_id = 10 OR course_id = 20) AND score >= 80`.\n\n**Coba:** bandingkan `score >= 80 AND course_id = 10` dengan `score >= 80 OR course_id = 10`. Mengapa enrollment #3 hanya ikut pada kondisi OR?\n\n## Bukti dari record sumber\n\nPisahkan pekerjaan: pilih record lewat WHERE, pilih kolom lewat SELECT, lalu susun urutan lewat ORDER BY. Cocokkan setiap hasil ke satu enrollment pada objek data.\n\n```sql\nSELECT enrollment_id, score\nFROM enrollments\nWHERE score >= 80\nORDER BY enrollment_id;\n```\n\n**Jelaskan:** sebutkan satu record yang gagal syarat dan alasan penolakannya.\n\n## Coba, bandingkan, jelaskan\n\nGunakan objek data untuk memeriksa record sumber, lalu jalankan contoh di lab. Ubah satu bagian, prediksi ulang, dan bandingkan hasilnya. 3D membantu mengikuti relasi; tabel hasil tetap 2D.\n\nDua latihan pertama membantumu memeriksa submateri dan bersifat opsional. Practice terakhir wajib untuk membuka materi berikutnya. Semua latihan dapat diulang; hasil Run bukan nilai asesmen.\n","example_sql":"SELECT enrollment_id, score FROM enrollments WHERE score >= 80 ORDER BY enrollment_id;","exercises":[{"type":"PSEUDOCODE","title":"Uji nilai batas","prompt":"Enrollment #5 bernilai 80. Kondisi mana menerima record ini?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"greater","text":"score > 80"},{"id":"inclusive","text":"score >= 80"},{"id":"less","text":"score < 80"}],"subtopic":"Batas perbandingan"},"answer":{"choiceId":"inclusive"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Minimal berarti nilai batas ikut diterima; bandingkan > dengan >=."}},"position":1,"is_required":false},{"type":"PSEUDOCODE","title":"Gabungkan dua syarat","prompt":"Hanya pendaftaran course_id 10 dengan score minimal 80 yang boleh ikut. Mana kondisinya?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"or","text":"course_id = 10 OR score >= 80"},{"id":"and","text":"course_id = 10 AND score >= 80"},{"id":"equal","text":"course_id = 10 AND score = 80"}],"subtopic":"AND dan OR"},"answer":{"choiceId":"and"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Kedua syarat harus benar pada record yang sama. OR menerima record yang hanya memenuhi satu syarat."}},"position":2,"is_required":false},{"type":"PREDICT_OUTPUT","title":"Tentukan record yang lolos","prompt":"Prediksi enrollment_id dan score untuk syarat minimal 80. Jangan sertakan header.","starter_code":"SELECT enrollment_id, score FROM enrollments WHERE score >= 80 ORDER BY enrollment_id;","config":{"public":{"columns":["enrollment_id","score"],"subtopic":"Record hasil"},"answer":{"output":"1 | 88\n2 | 90\n4 | 82\n5 | 80\n6 | 95"},"grading":{"mode":"table","columnTypes":["number","number"]},"feedback":{"correct":"Prediksi tepat. Sekarang ubah satu kondisi di lab dan bandingkan hasilnya.","retry":"Periksa batas tepat 80 dan keluarkan record bernilai 74; susun berdasarkan enrollment_id."}},"position":3,"is_required":true}]},{"slug":"mengurutkan-dan-membatasi","title":"Mengurutkan dan Membatasi Hasil","summary":"Cari nilai tertinggi dan pahami mengapa pengurutan harus dilakukan sebelum pembatasan.","content":"## Misi Kampus Mini\n\nPetugas ingin dua pendaftaran dengan nilai tertinggi. Pilih arah urutan yang tepat sebelum LIMIT.\n\n## ASC dan DESC\n\nORDER BY mengurutkan hasil, tidak mengubah urutan penyimpanan record. ASC berarti menaik; DESC menurun. Nilai berbeda pada enrollments.score membantu melihat dampaknya dengan jelas.\n\n**Coba:** jalankan ASC lalu DESC dan bandingkan record pertama.\n\n## Nilai seri dan tie-breaker\n\nJika nilai kolom urut sama, gunakan kolom kedua untuk menentukan urutan. Seluruh courses memiliki credits 3. `ORDER BY credits DESC, course_name ASC` mengurutkan nama saat credits seri.\n\n**Prediksi:** apakah LIMIT 2 tanpa urutan kedua selalu memilih pasangan mata kuliah yang sama? Tidak ada jaminan urutan untuk nilai seri tanpa pembeda.\n\n## LIMIT setelah urutan\n\nLIMIT membatasi jumlah hasil. Untuk dua nilai tertinggi, urutkan score DESC, gunakan enrollment_id sebagai pembeda, lalu LIMIT 2.\n\n```sql\nSELECT enrollment_id, score\nFROM enrollments\nORDER BY score DESC, enrollment_id ASC\nLIMIT 2;\n```\n\n**Jelaskan:** mengapa LIMIT 2 saja belum berarti dua nilai tertinggi?\n\n## Coba, bandingkan, jelaskan\n\nGunakan objek data untuk memeriksa record sumber, lalu jalankan contoh di lab. Ubah satu bagian, prediksi ulang, dan bandingkan hasilnya. 3D membantu mengikuti relasi; tabel hasil tetap 2D.\n\nDua latihan pertama membantumu memeriksa submateri dan bersifat opsional. Practice terakhir wajib untuk membuka materi berikutnya. Semua latihan dapat diulang; hasil Run bukan nilai asesmen.\n","example_sql":"SELECT enrollment_id, score FROM enrollments ORDER BY score DESC, enrollment_id ASC LIMIT 2;","exercises":[{"type":"PREDICT_OUTPUT","title":"Lihat urutan menaik","prompt":"Prediksi dua nilai terendah berdasarkan query berikut.","starter_code":"SELECT enrollment_id, score FROM enrollments ORDER BY score ASC, enrollment_id ASC LIMIT 2;","config":{"public":{"columns":["enrollment_id","score"],"subtopic":"Arah urutan"},"answer":{"output":"3 | 74\n5 | 80"},"grading":{"mode":"table","columnTypes":["number","number"]},"feedback":{"correct":"Prediksi tepat. Sekarang ubah satu kondisi di lab dan bandingkan hasilnya.","retry":"ASC menempatkan nilai kecil lebih dulu; LIMIT diterapkan pada urutan hasil."}},"position":1,"is_required":false},{"type":"PSEUDOCODE","title":"Pecahkan nilai seri","prompt":"Semua credits bernilai 3. Agar dua nama pertama konsisten, klausa apa yang kamu gunakan?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"limit","text":"LIMIT 2 saja"},{"id":"tie","text":"ORDER BY credits DESC, course_name ASC LIMIT 2"},{"id":"one","text":"ORDER BY credits DESC LIMIT 2"}],"subtopic":"Tie-breaker"},"answer":{"choiceId":"tie"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Kredit yang seri perlu kolom pembeda kedua sebelum dibatasi."}},"position":2,"is_required":false},{"type":"PREDICT_OUTPUT","title":"Temukan dua nilai tertinggi","prompt":"Prediksi enrollment_id dan score untuk dua pendaftaran teratas.","starter_code":"SELECT enrollment_id, score FROM enrollments ORDER BY score DESC, enrollment_id ASC LIMIT 2;","config":{"public":{"columns":["enrollment_id","score"],"subtopic":"LIMIT"},"answer":{"output":"6 | 95\n2 | 90"},"grading":{"mode":"table","columnTypes":["number","number"]},"feedback":{"correct":"Prediksi tepat. Sekarang ubah satu kondisi di lab dan bandingkan hasilnya.","retry":"DESC berarti nilai besar lebih dulu; cocokkan nilai dengan enrollment_id miliknya."}},"position":3,"is_required":true}]},{"slug":"menghubungkan-tabel","title":"Membaca Relasi dengan JOIN","summary":"Cocokkan key terlebih dahulu, lalu terjemahkan record penghubung menjadi informasi manusia.","content":"## Misi Kampus Mini\n\nSiapa yang mengikuti Basis Data dan berapa nilainya? Telusuri key pada objek sebelum menulis JOIN.\n\n## Dua tabel: cocokkan PK dan FK\n\nINNER JOIN memasangkan record yang memenuhi ON. Mulai dari enrollments dan students: `ON students.student_id = enrollments.student_id`. Membandingkan enrollment_id dengan student_id dapat menghasilkan pasangan salah meskipun angka tampak sama.\n\n```sql\nSELECT students.name, enrollments.score\nFROM enrollments\nJOIN students ON students.student_id = enrollments.student_id\nORDER BY enrollments.enrollment_id;\n```\n\n**Amati:** pilih enrollment #2. Temukan mahasiswa yang benar lewat student_id.\n\n## Mengapa nama bisa berulang?\n\nSatu baris hasil JOIN ini mewakili satu pendaftaran, bukan satu mahasiswa unik. Alya muncul dua kali karena mempunyai dua pendaftaran. JOIN tidak otomatis menyatukan atau membuang duplikasi entitas.\n\n**Coba:** tambahkan `WHERE students.student_id = 1` pada query dua tabel. Cocokkan setiap hasil ke dua enrollment milik Alya.\n\n## Tiga tabel dan alias\n\nTambahkan courses lewat course_id agar nama mata kuliah ikut terbaca. `AS s`, `AS e`, dan `AS c` adalah alias singkat untuk tabel, bukan tabel baru. Gunakan prefix saat nama kolom ada di lebih dari satu tabel.\n\n```sql\nSELECT s.name, c.course_name, e.score\nFROM enrollments AS e\nJOIN students AS s ON s.student_id = e.student_id\nJOIN courses AS c ON c.course_id = e.course_id\nWHERE c.course_code = 'IF102'\nORDER BY s.name;\n```\n\n**Jelaskan:** pilih course 20 di 2D/3D dan cocokkan dua pendaftaran terkait ke hasil query.\n\n## Coba, bandingkan, jelaskan\n\nGunakan objek data untuk memeriksa record sumber, lalu jalankan contoh di lab. Ubah satu bagian, prediksi ulang, dan bandingkan hasilnya. 3D membantu mengikuti relasi; tabel hasil tetap 2D.\n\nDua latihan pertama membantumu memeriksa submateri dan bersifat opsional. Practice terakhir wajib untuk membuka materi berikutnya. Semua latihan dapat diulang; hasil Run bukan nilai asesmen.\n","example_sql":"SELECT s.name, c.course_name, e.score FROM enrollments AS e JOIN students AS s ON s.student_id = e.student_id JOIN courses AS c ON c.course_id = e.course_id WHERE c.course_code = 'IF102' ORDER BY s.name;","exercises":[{"type":"PSEUDOCODE","title":"Pasangkan key, bukan urutan","prompt":"Pasangan ON mana menghubungkan pendaftaran dengan mahasiswa?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"ids","text":"enrollments.enrollment_id = students.student_id"},{"id":"keys","text":"enrollments.student_id = students.student_id"},{"id":"name","text":"enrollments.course_id = students.name"}],"subtopic":"Pasangan JOIN"},"answer":{"choiceId":"keys"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Ikuti FK student_id ke PK student_id; enrollment_id adalah identitas pendaftaran."}},"position":1,"is_required":false},{"type":"PREDICT_OUTPUT","title":"Mengapa Alya muncul dua kali?","prompt":"Prediksi nama dan nilai pada dua pendaftaran Alya.","starter_code":"SELECT s.name, e.score FROM enrollments AS e JOIN students AS s ON s.student_id = e.student_id WHERE s.student_id = 1 ORDER BY e.enrollment_id;","config":{"public":{"columns":["name","score"],"subtopic":"Satu-ke-banyak"},"answer":{"output":"Alya | 88\nAlya | 90"},"grading":{"mode":"table","columnTypes":["text","number"]},"feedback":{"correct":"Prediksi tepat. Sekarang ubah satu kondisi di lab dan bandingkan hasilnya.","retry":"Satu hasil mewakili satu enrollment. Mahasiswa yang sama dapat punya lebih dari satu hasil."}},"position":2,"is_required":false},{"type":"PREDICT_OUTPUT","title":"Temukan peserta Basis Data","prompt":"Prediksi nama, mata kuliah, dan nilai untuk kode IF102.","starter_code":"SELECT s.name, c.course_name, e.score FROM enrollments AS e JOIN students AS s ON s.student_id = e.student_id JOIN courses AS c ON c.course_id = e.course_id WHERE c.course_code = 'IF102' ORDER BY s.name;","config":{"public":{"columns":["name","course_name","score"],"subtopic":"Jalur tiga tabel"},"answer":{"output":"Alya | Basis Data | 90\nCitra | Basis Data | 80"},"grading":{"mode":"table","columnTypes":["text","text","number"]},"feedback":{"correct":"Prediksi tepat. Sekarang ubah satu kondisi di lab dan bandingkan hasilnya.","retry":"Cari course_id untuk IF102, lalu dua enrollment yang merujuk key itu dan mahasiswa masing-masing."}},"position":3,"is_required":true}]},{"slug":"merangkum-data","title":"Membuat Ringkasan Data","summary":"Kelompokkan pendaftaran dan jelaskan perbedaan jumlah peserta dengan rata-rata nilai.","content":"## Misi Kampus Mini\n\nKampus meminta jumlah peserta dan rata-rata nilai setiap mata kuliah, bukan daftar semua pendaftaran.\n\n## COUNT menghitung record\n\nCOUNT(*) menghitung baris hasil sumber. Dalam dataset ini setiap enrollment adalah satu pendaftaran. Jangan menyamakan jumlah enrollment dengan jumlah mahasiswa unik: Alya dan Bima masing-masing mempunyai dua enrollment.\n\n**Amati:** hitung 6 pendaftaran dan 4 mahasiswa. Query mana yang menjawab jumlah pendaftaran?\n\n## GROUP BY membentuk grup\n\nGROUP BY course_id merangkum pendaftaran per mata kuliah. Pilih course 10: anggota grupnya enrollment #1, #3, dan #6. COUNT untuk grup tersebut membaca tiga record, bukan jumlah kolom atau jumlah credits.\n\n```sql\nSELECT course_id, COUNT(*) AS participants\nFROM enrollments\nGROUP BY course_id\nORDER BY course_id;\n```\n\n**Coba:** ikuti hubungan course 20 untuk menemukan anggota grup yang lain.\n\n## AVG dan satu baris per grup\n\nAVG(score) menghitung rata-rata nilai anggota grup. Untuk course 10, (88 + 74 + 95) / 3 ≈ 85,67. ROUND(..., 2) membulatkan angka; tampilan 85 dan 85.00 bernilai sama. JOIN menambahkan nama mata kuliah; GROUP BY tetap menentukan satu baris per mata kuliah yang punya enrollment.\n\n**Jelaskan:** apakah peserta paling banyak selalu berarti rata-rata paling tinggi? Cocokkan jumlah dan rata-rata secara terpisah.\n\n## Coba, bandingkan, jelaskan\n\nGunakan objek data untuk memeriksa record sumber, lalu jalankan contoh di lab. Ubah satu bagian, prediksi ulang, dan bandingkan hasilnya. 3D membantu mengikuti relasi; tabel hasil tetap 2D.\n\nDua latihan pertama membantumu memeriksa submateri dan bersifat opsional. Practice terakhir wajib untuk membuka materi berikutnya. Semua latihan dapat diulang; hasil Run bukan nilai asesmen.\n","example_sql":"SELECT c.course_name, COUNT(e.enrollment_id) AS enrollment_count, ROUND(AVG(e.score), 2) AS average_score FROM courses AS c JOIN enrollments AS e ON e.course_id = c.course_id GROUP BY c.course_id, c.course_name ORDER BY average_score DESC;","exercises":[{"type":"PREDICT_OUTPUT","title":"Hitung pendaftaran","prompt":"Prediksi jumlah seluruh pendaftaran, bukan jumlah mahasiswa unik.","starter_code":"SELECT COUNT(*) AS total FROM enrollments;","config":{"public":{"columns":["total"],"subtopic":"COUNT"},"answer":{"output":"6"},"grading":{"mode":"table","columnTypes":["number"]},"feedback":{"correct":"Prediksi tepat. Sekarang ubah satu kondisi di lab dan bandingkan hasilnya.","retry":"COUNT membaca baris sumber; satu mahasiswa dapat terdaftar pada beberapa mata kuliah."}},"position":1,"is_required":false},{"type":"PSEUDOCODE","title":"Pahami anggota grup","prompt":"Untuk GROUP BY course_id, satu baris ringkasan mewakili apa?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"student","text":"Satu mahasiswa tanpa memperhatikan pendaftarannya."},{"id":"course","text":"Satu mata kuliah dan pendaftaran yang merujuk course_id itu."},{"id":"column","text":"Satu kolom pada tabel enrollments."}],"subtopic":"GROUP BY"},"answer":{"choiceId":"course"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Cari kolom pengelompokan dan record dengan nilai key yang sama."}},"position":2,"is_required":false},{"type":"PREDICT_OUTPUT","title":"Bandingkan jumlah dan rata-rata","prompt":"Prediksi nama mata kuliah, jumlah peserta, dan rata-rata nilai. Ikuti urutan average_score menurun.","starter_code":"SELECT c.course_name, COUNT(e.enrollment_id) AS enrollment_count, ROUND(AVG(e.score), 2) AS average_score FROM courses AS c JOIN enrollments AS e ON e.course_id = c.course_id GROUP BY c.course_id, c.course_name ORDER BY average_score DESC;","config":{"public":{"columns":["course_name","enrollment_count","average_score"],"subtopic":"AVG"},"answer":{"output":"Sistem Informasi | 3 | 85.67\nBasis Data | 2 | 85.0\nMatematika Diskrit | 1 | 82.0"},"grading":{"mode":"table","columnTypes":["text","number","number"]},"feedback":{"correct":"Prediksi tepat. Sekarang ubah satu kondisi di lab dan bandingkan hasilnya.","retry":"Bentuk grup dari enrollment yang merujuk course yang sama, lalu hitung jumlah dan rata-rata secara terpisah."}},"position":3,"is_required":true}]},{"slug":"tantangan-query-kampus","title":"Investigasi Query Kampus","summary":"Gabungkan relasi, kondisi, dan ringkasan untuk menjawab pertanyaan kampus.","content":"## Misi Kampus Mini\n\nLaporkan jumlah peserta bernilai minimal 85 dan rata-ratanya per mata kuliah. Bandingkan dengan ambang 80: perubahan apa yang terlihat?\n\n## Terjemahkan permintaan ke data\n\nNilai berada di enrollments, nama mata kuliah di courses. Gunakan relasi course_id untuk menggabungkan keduanya. Pertanyaan ini tidak membutuhkan students karena nama mahasiswa tidak diminta.\n\n**Amati:** tunjuk kolom yang menjawab setiap bagian permintaan sebelum menyusun query.\n\n## Filter sebelum ringkasan\n\nWHERE score >= 85 memilih enrollment sebelum GROUP BY membentuk grup. Rata-rata hanya memakai record yang lolos, bukan semua peserta. Menampilkan nama mata kuliah yang sama tidak berarti grup masih berisi record yang sama.\n\n**Prediksi:** course 10 kehilangan enrollment bernilai 74. Bagaimana jumlah dan rata-ratanya berubah?\n\n## Periksa hasil, bukan hanya query berhasil\n\nGunakan COUNT dan AVG, urutkan rata-rata menurun, dan gunakan nama sebagai pembeda jika seri. JOIN yang salah dapat memberi hasil terlihat masuk akal tetapi berasal dari pasangan salah.\n\n**Coba:** ubah batas 85 menjadi 80. Jelaskan mata kuliah yang baru muncul dan anggota grup yang bertambah. Keberhasilan query berarti sintaks diterima; ketepatan jawaban tetap perlu dicek lewat record sumber.\n\n## Coba, bandingkan, jelaskan\n\nGunakan objek data untuk memeriksa record sumber, lalu jalankan contoh di lab. Ubah satu bagian, prediksi ulang, dan bandingkan hasilnya. 3D membantu mengikuti relasi; tabel hasil tetap 2D.\n\nDua latihan pertama membantumu memeriksa submateri dan bersifat opsional. Practice terakhir wajib untuk membuka materi berikutnya. Semua latihan dapat diulang; hasil Run bukan nilai asesmen.\n","example_sql":"SELECT c.course_name, COUNT(e.enrollment_id) AS enrollment_count, ROUND(AVG(e.score), 2) AS average_score FROM courses AS c JOIN enrollments AS e ON e.course_id = c.course_id WHERE e.score >= 85 GROUP BY c.course_id, c.course_name ORDER BY average_score DESC, c.course_name;","exercises":[{"type":"PSEUDOCODE","title":"Gunakan tabel yang dibutuhkan","prompt":"Permintaan hanya nama mata kuliah, jumlah peserta, dan rata-rata nilai. Tabel mana cukup?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"one","text":"students saja"},{"id":"pair","text":"courses dan enrollments"},{"id":"none","text":"courses saja, karena memiliki credits"}],"subtopic":"Terjemahkan permintaan"},"answer":{"choiceId":"pair"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Temukan score pada enrollments dan nama pada courses; hubungkan melalui course_id."}},"position":1,"is_required":false},{"type":"PSEUDOCODE","title":"Susun alur penyelidikan","prompt":"Susun alur konsep untuk menghitung ringkasan peserta yang lolos ambang.","starter_code":null,"config":{"public":{"mode":"order","blocks":[{"id":"group","text":"Kelompokkan yang lolos per course_id dan hitung COUNT/AVG."},{"id":"source","text":"Cocokkan enrollment dengan mata kuliah lewat course_id."},{"id":"filter","text":"Pilih enrollment dengan score >= 85."},{"id":"display","text":"Tampilkan dan urutkan ringkasan."}],"subtopic":"Filter dan grup"},"answer":{"order":["source","filter","group","display"]},"feedback":{"correct":"Urutan tepat. Hubungkan setiap langkah dengan data yang kamu amati.","retry":"Kondisi WHERE menentukan anggota grup sebelum nilai agregat dihitung."}},"position":2,"is_required":false},{"type":"PREDICT_OUTPUT","title":"Selesaikan laporan kampus","prompt":"Prediksi ringkasan untuk nilai minimal 85. Jelaskan mengapa beberapa mata kuliah tidak muncul.","starter_code":"SELECT c.course_name, COUNT(e.enrollment_id) AS enrollment_count, ROUND(AVG(e.score), 2) AS average_score FROM courses AS c JOIN enrollments AS e ON e.course_id = c.course_id WHERE e.score >= 85 GROUP BY c.course_id, c.course_name ORDER BY average_score DESC, c.course_name;","config":{"public":{"columns":["course_name","enrollment_count","average_score"],"subtopic":"Verifikasi laporan"},"answer":{"output":"Sistem Informasi | 2 | 91.5\nBasis Data | 1 | 90.0"},"grading":{"mode":"table","columnTypes":["text","number","number"]},"feedback":{"correct":"Prediksi tepat. Sekarang ubah satu kondisi di lab dan bandingkan hasilnya.","retry":"Hanya enrollment yang lolos batas ikut dihitung. Mata kuliah tanpa enrollment yang lolos tidak muncul pada INNER JOIN ini."}},"position":3,"is_required":true}]},{"slug":"menambahkan-record-dengan-insert","title":"Menambahkan Record dengan INSERT","summary":"Tambahkan satu record baru dan selidiki aturan key sebelum menerapkan perubahan.","content":"## Misi Kampus Mini\n\nEka akan bergabung sebagai mahasiswa angkatan 2026. Tambahkan tepat satu record; jangan mengubah mahasiswa yang sudah ada.\n\n## Pasangan kolom dan nilai\n\nINSERT menambah record. Tuliskan daftar kolom agar urutan nilai jelas: student_id, name, cohort berpasangan dengan 5, Eka, 2026. Teks memakai kutip tunggal.\n\n```sql\nINSERT INTO students (student_id, name, cohort)\nVALUES (5, 'Eka', '2026');\n```\n\n**Prediksi:** jumlah students bertambah dari 4 menjadi berapa? Apakah enrollments juga otomatis bertambah?\n\n## Key menjaga konsistensi\n\nPK baru harus unik. student_id 1 sudah dipakai sehingga tidak dapat dipakai Eka. Jika menambah enrollment, student_id dan course_id harus merujuk record induk yang ada; nama Eka saja tidak cukup sebagai rujukan.\n\n**Coba:** periksa key 5 sebelum insert. Setelah reset, coba key yang sudah ada dan baca alasan penolakan.\n\n## Preview, terapkan, verifikasi\n\nLab membatasi satu record per perintah. Preview belum mengubah tabel; terapkan setelah kolom dan nilainya benar. Setelah diterapkan, objek 2D/3D memperlihatkan record baru. Verifikasi dengan `SELECT * FROM students WHERE student_id = 5;`.\n\n**Jelaskan:** reset menghapus perubahan latihan lokal, bukan menghapus akun atau progres belajarmu.\n\n## Coba, bandingkan, jelaskan\n\nGunakan objek data untuk memeriksa record sumber, lalu jalankan contoh di lab. Ubah satu bagian, prediksi ulang, dan bandingkan hasilnya. 3D membantu mengikuti relasi; tabel hasil tetap 2D.\n\nDua latihan pertama membantumu memeriksa submateri dan bersifat opsional. Practice terakhir wajib untuk membuka materi berikutnya. Semua latihan dapat diulang; hasil Run bukan nilai asesmen.\n","example_sql":"INSERT INTO students (student_id, name, cohort) VALUES (5, 'Eka', '2026');","exercises":[{"type":"PSEUDOCODE","title":"Pasangkan INSERT dan VALUES","prompt":"Susun bagian perintah untuk menambah Eka dengan kolom eksplisit.","starter_code":null,"config":{"public":{"mode":"order","blocks":[{"id":"values","text":"VALUES (5, 'Eka', '2026');"},{"id":"insert","text":"INSERT INTO students"},{"id":"columns","text":"(student_id, name, cohort)"}],"subtopic":"Kolom dan nilai"},"answer":{"order":["insert","columns","values"]},"feedback":{"correct":"Urutan tepat. Hubungkan setiap langkah dengan data yang kamu amati.","retry":"Daftar kolom menentukan arti masing-masing nilai VALUES."}},"position":1,"is_required":false},{"type":"PSEUDOCODE","title":"Uji rujukan enrollment","prompt":"Sebelum student_id 5 dibuat, kamu menambah enrollment untuk student_id 5. Apa yang terjadi?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"auto","text":"SQLite otomatis membuat mahasiswa baru."},{"id":"reject","text":"Foreign key menolak rujukan karena mahasiswa belum ada."},{"id":"name","text":"Key tidak penting jika nama mahasiswa diketahui."}],"subtopic":"Constraint"},"answer":{"choiceId":"reject"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Foreign key menunjuk record yang sudah ada pada tabel induk."}},"position":2,"is_required":false},{"type":"PSEUDOCODE","title":"Tambahkan Eka dengan aman","prompt":"Pilih INSERT untuk mahasiswa baru, key 5, nama Eka, angkatan 2026.","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"duplicate","text":"INSERT INTO students (student_id, name, cohort) VALUES (1, 'Eka', '2026');"},{"id":"valid","text":"INSERT INTO students (student_id, name, cohort) VALUES (5, 'Eka', '2026');"},{"id":"swapped","text":"INSERT INTO students (student_id, name, cohort) VALUES (5, '2026', 'Eka');"}],"subtopic":"Verifikasi INSERT"},"answer":{"choiceId":"valid"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Periksa key yang belum dipakai dan urutan nilai terhadap kolom."}},"position":3,"is_required":true}]},{"slug":"mengubah-record-dengan-update","title":"Mengubah Record dengan UPDATE","summary":"Perbaiki satu nilai dengan target primary key dan bukti sebelum/sesudah.","content":"## Misi Kampus Mini\n\nNilai enrollment #3 salah tercatat 74; nilai yang benar 78. Perbaiki hanya pendaftaran tersebut, bukan semua pendaftaran Bima.\n\n## Temukan satu target\n\nMulai dengan `SELECT * FROM enrollments WHERE enrollment_id = 3;`. Bima mempunyai dua pendaftaran; student_id 2 bukan target yang cukup sempit. PK enrollment_id mengidentifikasi satu record.\n\n**Amati:** pilih Bima, lalu bedakan dua enrollment terkait. Mana yang harus berubah?\n\n## SET untuk nilai, WHERE untuk target\n\nSET menentukan atribut baru; WHERE menentukan record yang menerima perubahan.\n\n```sql\nUPDATE enrollments\nSET score = 78\nWHERE enrollment_id = 3;\n```\n\nTanpa WHERE, seluruh record bisa berubah pada database biasa; lab sengaja menolaknya. Jangan mengandalkan penolakan lab sebagai pengganti kebiasaan memilih target.\n\n## Bukti sebelum dan sesudah\n\nPreview memperlihatkan score 74 → 78 tanpa langsung menyimpan perubahan. Konfirmasi hanya jika record dan nilai benar. Objek lokal berubah setelah diterapkan; record enrollment #4 tetap bernilai 82. Gunakan SELECT dengan predicate yang sama untuk verifikasi.\n\n**Coba:** ulangi dengan reset. Jelaskan mengapa jumlah record tetap enam meskipun nilai satu record berubah.\n\n## Coba, bandingkan, jelaskan\n\nGunakan objek data untuk memeriksa record sumber, lalu jalankan contoh di lab. Ubah satu bagian, prediksi ulang, dan bandingkan hasilnya. 3D membantu mengikuti relasi; tabel hasil tetap 2D.\n\nDua latihan pertama membantumu memeriksa submateri dan bersifat opsional. Practice terakhir wajib untuk membuka materi berikutnya. Semua latihan dapat diulang; hasil Run bukan nilai asesmen.\n","example_sql":"UPDATE enrollments SET score = 78 WHERE enrollment_id = 3;","exercises":[{"type":"PSEUDOCODE","title":"Target satu pendaftaran","prompt":"Bima memiliki enrollment #3 dan #4. Predicate mana tepat untuk memperbaiki #3 saja?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"student","text":"student_id = 2"},{"id":"pk","text":"enrollment_id = 3"},{"id":"score","text":"score >= 74"}],"subtopic":"Target UPDATE"},"answer":{"choiceId":"pk"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Identitas mahasiswa dapat cocok dengan beberapa pendaftaran; gunakan PK record yang akan diubah."}},"position":1,"is_required":false},{"type":"PSEUDOCODE","title":"Bandingkan sebelum dan sesudah","prompt":"Setelah UPDATE #3 menjadi 78 diterapkan, apa yang benar?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"rows","text":"Ada tujuh enrollment karena UPDATE menambah record."},{"id":"all","text":"Semua nilai Bima menjadi 78."},{"id":"one","text":"Ada enam enrollment; #3 menjadi 78 dan #4 tetap 82."}],"subtopic":"SET dan dampak"},"answer":{"choiceId":"one"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"UPDATE mengubah atribut record yang cocok, bukan menambah baris atau mengubah semua record mahasiswa."}},"position":2,"is_required":false},{"type":"FLOWCHART","title":"Perbaiki nilai dengan bukti","prompt":"Susun langkah aman untuk memperbaiki enrollment #3.","starter_code":null,"config":{"public":{"mode":"order","blocks":[{"id":"verify","text":"Verifikasi score dengan SELECT untuk enrollment_id 3."},{"id":"preview","text":"Baca target dan bandingkan score 74 → 78 pada preview."},{"id":"apply","text":"Terapkan UPDATE score = 78 WHERE enrollment_id = 3."}],"subtopic":"Verifikasi UPDATE"},"answer":{"order":["preview","apply","verify"]},"feedback":{"correct":"Urutan tepat. Hubungkan setiap langkah dengan data yang kamu amati.","retry":"Periksa target sebelum menerapkan perubahan, lalu verifikasi nilai tersimpan."}},"position":3,"is_required":true}]},{"slug":"menghapus-record-dengan-delete","title":"Menghapus Record dengan DELETE","summary":"Hapus satu pendaftaran dengan aman dan pahami rujukan yang membatasi penghapusan induk.","content":"## Misi Kampus Mini\n\nEnrollment #6 dibatalkan. Hapus pendaftarannya, bukan langsung mahasiswa Danu yang masih dirujuk.\n\n## DELETE memilih record untuk dihapus\n\nDELETE menghilangkan record, bukan sekadar mengosongkan score. Periksa `SELECT * FROM enrollments WHERE enrollment_id = 6;` lalu gunakan predicate PK yang sama untuk DELETE.\n\n```sql\nDELETE FROM enrollments\nWHERE enrollment_id = 6;\n```\n\n**Prediksi:** berapa enrollment tersisa? Apakah students ikut berkurang?\n\n## Induk yang masih dirujuk\n\nDanu adalah students #4; enrollment #6 merujuknya. Menghapus students #4 lebih dulu ditolak foreign key. Pada dataset ini tidak ada cascading delete. Menghapus enrollment #6 menghapus satu hubungan, bukan otomatis menghapus Danu atau mata kuliahnya.\n\n**Coba:** setelah reset, pratinjau DELETE students #4 untuk melihat batas relasi. Jangan mematikan foreign key.\n\n## Konfirmasi dan pulihkan latihan\n\nPreview menampilkan record target dan jumlah yang akan dihapus. Setelah diterapkan, objek enrollment #6 hilang dan hubungan terkaitnya ikut hilang. Verifikasi dengan SELECT, lalu Reset data untuk mengembalikan enam pendaftaran.\n\n**Jelaskan:** bedakan perubahan isi tabel, jumlah record, dan perubahan schema. Kamu sudah dapat mengikuti data dari relasi, membaca hasil, sampai perubahan yang aman.\n\n## Coba, bandingkan, jelaskan\n\nGunakan objek data untuk memeriksa record sumber, lalu jalankan contoh di lab. Ubah satu bagian, prediksi ulang, dan bandingkan hasilnya. 3D membantu mengikuti relasi; tabel hasil tetap 2D.\n\nDua latihan pertama membantumu memeriksa submateri dan bersifat opsional. Practice terakhir wajib untuk membuka materi berikutnya. Semua latihan dapat diulang; hasil Run bukan nilai asesmen.\n","example_sql":"DELETE FROM enrollments WHERE enrollment_id = 6;","exercises":[{"type":"PSEUDOCODE","title":"Pilih target DELETE","prompt":"Untuk membatalkan enrollment #6 saja, predicate mana digunakan?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"course","text":"course_id = 10"},{"id":"all","text":"Tanpa WHERE agar lebih cepat."},{"id":"pk","text":"enrollment_id = 6"}],"subtopic":"Target DELETE"},"answer":{"choiceId":"pk"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Satu course memiliki beberapa pendaftaran; gunakan identitas record yang akan dibatalkan."}},"position":1,"is_required":false},{"type":"PSEUDOCODE","title":"Mengapa induk ditolak?","prompt":"Sebelum #6 dihapus, mengapa DELETE students #4 ditolak?","starter_code":null,"config":{"public":{"mode":"choice","options":[{"id":"cascade","text":"Semua anak selalu dihapus otomatis."},{"id":"fk","text":"Enrollment #6 masih merujuk student_id 4 melalui FK."},{"id":"score","text":"Nilai 95 terlalu besar untuk DELETE."}],"subtopic":"Foreign key"},"answer":{"choiceId":"fk"},"feedback":{"correct":"Tepat. Coba jelaskan alasanmu dengan menunjuk record atau key pada data.","retry":"Periksa enrollment yang masih menunjuk mahasiswa tersebut; dataset tidak memakai cascade."}},"position":2,"is_required":false},{"type":"FLOWCHART","title":"Batalkan lalu periksa","prompt":"Susun alur membatalkan enrollment #6 dan memulihkan data latihan.","starter_code":null,"config":{"public":{"mode":"order","blocks":[{"id":"reset","text":"Reset data setelah mengamati hasil."},{"id":"apply","text":"Konfirmasi DELETE enrollment_id 6."},{"id":"verify","text":"Verifikasi #6 tidak ada; students tetap empat record."},{"id":"preview","text":"Periksa preview target enrollment #6 dan jumlah satu record."}],"subtopic":"Verifikasi DELETE"},"answer":{"order":["preview","apply","verify","reset"]},"feedback":{"correct":"Urutan tepat. Hubungkan setiap langkah dengan data yang kamu amati.","retry":"Preview mendahului penerapan. Verifikasi sebelum reset agar perubahan bisa diamati."}},"position":3,"is_required":true}]}]$curriculum$::jsonb);

do $guard$
declare n integer;
begin
  select count(*) into n from public.lessons l
  join public.chapters c on c.id=l.chapter_id
  join public.learning_paths p on p.id=c.learning_path_id
  where p.slug='database-fundamentals' and l.is_published
    and l.slug in (select x->>'slug' from interactive_lesson_seed s cross join lateral jsonb_array_elements(s.payload) x);
  if n <> 11 then raise exception 'Expected 11 matching published lessons; found %',n; end if;
  select count(*) into n from public.exercises e
  join public.lessons l on l.id=e.lesson_id
  join public.chapters c on c.id=l.chapter_id
  join public.learning_paths p on p.id=c.learning_path_id
  where p.slug='database-fundamentals' and l.is_published and e.is_required and e.is_published;
  if n <> 11 then raise exception 'Expected 11 existing mandatory exercises; found %',n; end if;
end $guard$;

with seed as (
 select x from interactive_lesson_seed s cross join lateral jsonb_array_elements(s.payload) x
)
update public.lessons l set title=seed.x->>'title', summary=seed.x->>'summary', content=seed.x->>'content', example_sql=seed.x->>'example_sql'
from seed, public.chapters c, public.learning_paths p
where l.slug=seed.x->>'slug' and l.chapter_id=c.id and c.learning_path_id=p.id and p.slug='database-fundamentals';

with seed as (
 select x->>'slug' slug,e from interactive_lesson_seed s cross join lateral jsonb_array_elements(s.payload) x
 cross join lateral jsonb_array_elements(x->'exercises') e where (e->>'is_required')::boolean
)
update public.exercises existing set position=3, title=seed.e->>'title',prompt=seed.e->>'prompt',
 type=(seed.e->>'type')::public.exercise_type, starter_code=seed.e->>'starter_code', config=seed.e->'config'
from seed, public.lessons l, public.chapters c, public.learning_paths p
where existing.lesson_id=l.id and existing.is_required and existing.is_published and l.slug=seed.slug
 and l.chapter_id=c.id and c.learning_path_id=p.id and p.slug='database-fundamentals';

insert into public.exercises(lesson_id,type,title,prompt,starter_code,config,position,is_required,is_published)
select l.id,(e->>'type')::public.exercise_type,e->>'title',e->>'prompt',e->>'starter_code',e->'config',(e->>'position')::integer,false,true
from interactive_lesson_seed s cross join lateral jsonb_array_elements(s.payload) x
cross join lateral jsonb_array_elements(x->'exercises') e
join public.lessons l on l.slug=x->>'slug'
join public.chapters c on c.id=l.chapter_id
join public.learning_paths p on p.id=c.learning_path_id
where p.slug='database-fundamentals' and not (e->>'is_required')::boolean
on conflict (lesson_id,position) do update set type=excluded.type,title=excluded.title,prompt=excluded.prompt,
 starter_code=excluded.starter_code,config=excluded.config,is_required=false,is_published=true;

do $verify$
begin
 if exists (
  select l.id from public.lessons l join public.chapters c on c.id=l.chapter_id join public.learning_paths p on p.id=c.learning_path_id
  left join public.exercises e on e.lesson_id=l.id and e.is_published
  where p.slug='database-fundamentals' and l.is_published
  group by l.id having count(e.id)<>3 or count(e.id) filter(where e.is_required)<>1
 ) then raise exception 'Each lesson must have two optional and one mandatory check'; end if;
 if exists (
  select 1 from public.exercises e join public.lessons l on l.id=e.lesson_id
  join public.chapters c on c.id=l.chapter_id join public.learning_paths p on p.id=c.learning_path_id
  where p.slug='database-fundamentals' and e.is_published
  and (e.public_config ? 'answer' or e.public_config ? 'grading' or e.public_config ? 'feedback')
 ) then raise exception 'Private grading fields in public configuration'; end if;
end $verify$;
